--- a/src/Pricing/PriceList.php
+++ b/src/Pricing/PriceList.php
@@ -12,16 +12,30 @@ final class PriceList

     public function __construct(private PriceRepository $prices) {}

-    public function forClinic(int $clinicId): array
-    {
-        return $this->prices->common();
+    /** @return array<int|string, int> код услуги => цена в копейках */
+    public function forClinic(int $clinicId): array
+    {
+        $common = $this->prices->common();
+        $own = $this->prices->byClinic($clinicId);
+
+        $merged = array_merge($common, $own);
+
+        ksort($merged);
+
+        return $merged;
     }

     public function priceOf(int $clinicId, string $code): ?int
     {
         return $this->forClinic($clinicId)[$code] ?? null;
     }
 }
